+	setEnv(t, with(map[string]string{
+		"GITEA_MQ_GITHUB_APP_ID":         "12345",
+		"GITEA_MQ_GITHUB_PRIVATE_KEY":    "-----BEGIN PRIVATE KEY-----\nfake\n-----END PRIVATE KEY-----",
+		"GITEA_MQ_GITHUB_WEBHOOK_SECRET": "ghsecret",
+		"GITEA_MQ_GITHUB_REPOS":          "org/app",
