+	ctx := context.Background()
+
+	prs, err := f.ListOpenPRs(ctx, "org", "app")
+	if err != nil {
+		t.Fatalf("ListOpenPRs: %v", err)
+	}
+	if len(prs) != 2 {
+		t.Fatalf("len = %d, want 2", len(prs))
+	}
+
+	pr, err := f.GetPR(ctx, "org", "app", 1)
+	if err != nil {
+		t.Fatalf("GetPR: %v", err)
