+	if got["ci/build"].State != pg.CheckStateSuccess || got["ci/build"].TargetURL != "https://ci/1" {
+		t.Errorf("ci/build = %+v", got["ci/build"])
+	}
+	if got["ci/test"].State != pg.CheckStatePending {
+		t.Errorf("ci/test = %+v", got["ci/test"])
+	}
