+	if err != nil {
+		return "", false, fmt.Errorf("resolve base %s: %w", base, err)
+	}
+	baseSHA := baseRef.GetObject().GetSHA()
+
+	_, resp, err := c.Git.CreateRef(ctx, owner, name, gh.CreateRef{
+		Ref: "refs/heads/" + branch,
+		SHA: baseSHA,
+	})
